/**
 * Test 203: The hosted demo notebook
 * Covers: REQ-FILE-026
 *
 * site/demo-workspace.json is what the Pages workflow embeds into the live
 * app. It is generated by driving the real app through the bridge, so this
 * test guards the result rather than the generator: the notebook must open,
 * showcase scrolls and the open canvas, and every block must fit its band.
 */
import { test, expect } from '@playwright/test';
import fs from 'node:fs';
import path from 'node:path';
import { waitForCanvasReady } from '../helpers';

const DEMO = JSON.parse(fs.readFileSync(path.resolve('site/demo-workspace.json'), 'utf8'));

test.describe('203 - Hosted demo notebook', () => {
  test('the notebook showcases scrolls and the open canvas, and every block fits its band', async ({ page }) => {
    const pages = DEMO.sections.flatMap((s: any) => s.pages.map((p: any) => ({ ...p, section: s.title })));
    const byTitle = (t: string) => pages.find((p: any) => p.title === t);

    const start = byTitle('Start here');
    const telemetry = byTitle('Telemetry gateway');
    const board = byTitle('Whiteboard');
    expect(start && telemetry && board).toBeTruthy();
    expect(start.scrolls.map((s: any) => s.title)).toEqual(['Your canvas', 'Agent workspace']);
    expect(telemetry.scrolls.map((s: any) => s.title)).toEqual(['Requirements', 'Design']);
    expect(board.settings?.backgroundMode).toBe('none');
    expect(board.nodes.filter((n: any) => n.type === 'shape').length).toBeGreaterThanOrEqual(5);
    expect((board.strokes ?? []).length).toBeGreaterThanOrEqual(2);
    expect(telemetry.nodes.some((n: any) => n.type === 'shape' && n.data?.label?.text)).toBe(true);
    expect((telemetry.strokes ?? []).length).toBeGreaterThanOrEqual(1);

    // Every block on a page with named scrolls sits inside one band, and no
    // page still carries the "# Title" block create_page seeds by default
    // next to a heading of its own.
    await page.goto('/');
    await waitForCanvasReady(page);
    const fit = await page.evaluate(async (data) => {
      const layout = await import('/src/utils/pageLayout.ts');
      const problems: string[] = [];
      for (const section of data.sections) {
        for (const p of section.pages) {
          if (!p.scrolls?.some((s: any) => s.title)) continue;
          for (const n of p.nodes) {
            // Blocks only: diagram members carry a groupId and may hang
            // outside their frame (port labels do), which is not a fit problem.
            if (n.type !== 'text' || n.groupId) continue;
            const col = layout.columnAt(n.x, p.scrolls);
            const left = layout.columnLeft(col, p.scrolls);
            const width = layout.columnWidth(col, p.scrolls);
            if (n.x < left - 1 || n.x + n.width > left + width + 1) problems.push(`${p.title}: ${n.id} overflows band ${col}`);
          }
        }
      }
      return problems;
    }, DEMO);
    expect(fit, fit.join('; ')).toEqual([]);
  });

  test('the notebook opens in the app with every page rendering and no console errors', async ({ page }) => {
    const errors: string[] = [];
    page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()); });
    page.on('pageerror', (e) => errors.push(String(e)));
    await page.goto('/');
    await waitForCanvasReady(page);
    const counts = await page.evaluate(async (data) => {
      const S = (window as any).__POWERNOTE_STORES__;
      S.workspace.setState({ workspace: data });
      const out: Record<string, number> = {};
      for (const section of data.sections) {
        for (const p of section.pages) {
          S.workspace.getState().setActivePage(section.id, p.id);
          S.canvas.getState().loadPageNodes(p.nodes ?? []);
          S.draw.getState().loadPageStrokes(p.strokes ?? []);
          await new Promise((r) => setTimeout(r, 400));
          const stage = (window as any).Konva.stages[0];
          out[p.title] = stage.find((n: any) => typeof n.getAttr === 'function' && n.getAttr('nodeId')).length;
        }
      }
      return out;
    }, DEMO);
    for (const [title, n] of Object.entries(counts)) expect(n, `${title} rendered nothing`).toBeGreaterThan(0);
    expect(errors).toEqual([]);
  });
});
